export function lookupMapByLocation(locName, townFallback) {
  if (!locName) return null;
  if (AUTHENTIC_MAPS_LOOKUP[locName]) {
    return AUTHENTIC_MAPS_LOOKUP[locName];
  }
  // Try partial key
  const norm = locName.toLowerCase().trim();
  for (const [key, val] of Object.entries(AUTHENTIC_MAPS_LOOKUP)) {
    if (key.toLowerCase().includes(norm) || norm.includes(key.toLowerCase())) {
      return val;
    }
  }
  return null;
}
